const { def, CH, SR, TAU, N, St, buf, noise, pink, brown, band, lp, hp, bp, lp4, hp4, svf, pk, hs, ls, env, curve, mul, mix, unit, unitr, pulse, bank, hit, ping, bubble, poisson, slip, air, wander, clamp, lerp, smooth, thud, nb, grain, crumbs, rustle, bubbles, cloth, whoosh, whistle, reversed, cluster, fadeEnds, dense, strike, flesh, squelch, lightning, glugs, fracture, render } = K;

// ================================================================ e1
def('box_close', { d: 'one face of the living cube folds shut: stone drags on stone, an eyelid inside it seals', hear: 'wet heavy stone grinding shut', sync: 0, hi: 4200 }, (o, r) => {
  const st = new St(.8), p = o.pan ?? 0, f = r.u(.85, 1.15), d = .3, n = N(d), x = band(r, n, 80, 2400, noise), w = wander(r, n, 70), w2 = wander(r, n, 240); for (let i = 0; i < n; i++) x[i] *= Math.sin(Math.PI * Math.pow(i / n, .8)) * (.2 + .8 * Math.pow(.5 + .5 * w[i], 2)) * (.5 + .5 * w2[i]); const y = bank(x, dense(r, { lo: 95 * f, hi: 1900, n: 34, t60: .05, roll: .5, tilt: .35 }), N(d + .1)); st.add(unit(y), { g: .85, pan: p }); mix(st.l, x, .22); mix(st.r, x, .22);
  squelch(st, r, { at: .15, dur: .22, f0: 240, f1: 1500, q: 1.8, rate: 52, a: .6, pan: p, shape: u => Math.sin(Math.PI * Math.pow(u, .7)), gate: .85 }); strike(st, r, .28, dense(r, { lo: 88 * f, hi: 1500, n: 28, t60: .13, roll: .7, tilt: .3 }), { tc: .003, rough: 1.2, a: .9, pan: p, hits: [[0, 1], [.019, .3]] }); flesh(st, r, .28, { a: .5, pan: p, mass: 1, skin: .4 }); return st;
});
def('box_shut', { d: 'the cube is shut: the last stone seats and the air inside is gone', hear: 'a heavy stone box slamming shut', sync: .012, hi: 4400 }, (o, r) => { const st = new St(1.4), T = .012; strike(st, r, T, dense(r, { lo: 110, hi: 3000, n: 60, t60: .3, roll: .7, tilt: .1 }), { tc: .0014, rough: 1.6, a: 1, hits: [[0, 1], [.026, .3], [.041, .15]] }); flesh(st, r, T, { a: .5, mass: 1, skin: .5 }); thud(st, T, 78, 40, .5, 1.2); nb(st, r, T, 300, 2300, .0006, .09, 1.4, { wide: .4 }); const n = N(.4), s = band(r, n, 140, 1600, pink); svf(s, t => 950 * Math.exp(-t * 7) + 130, 1.6, 'bp'); mul(s, t => smooth(t / .03) * Math.pow(1 - t / .4, 1.6)); st.add(unit(s), { at: .05, g: .4 }); squelch(st, r, { at: .05, dur: .22, f0: 200, f1: 900, q: 2, rate: 22, a: .3, shape: u => 1 - u }); return st; });
def('box_clink', { d: 'a small heavy stone cube lands on tile and bounces', hear: 'a small stone block clinking on a tile floor', sync: 0, hi: 5000, def: { bounces: 1 } }, (o, r) => { const st = new St(1.6), p = o.pan ?? 0; let t = 0, v = 1, gap = .21; const cube = dense(r, { lo: 520, hi: 3600, n: 26, t60: .035, roll: .2, tilt: .05 }), tile = dense(r, { lo: 170, hi: 1300, n: 18, t60: .05, roll: .5, tilt: .2 }); for (let k = 0; k < o.bounces; k++) { const hits = [[0, v], [r.u(.005, .009), v * .4], [r.u(.013, .02), v * .18]]; strike(st, r, t, cube, { tc: .0011, rough: 1.6, a: .85 * v, pan: p, hits }); strike(st, r, t, tile, { tc: .0016, rough: 1.4, a: .7 * v, pan: p, hits }); nb(st, r, t, 600, 2600, .0004, .03, .9 * v, { pan: p }); flesh(st, r, t, { a: .4 * v, pan: p, mass: 1, skin: .2 }); t += gap * r.u(.95, 1.05); gap *= .6; v *= .55; } return st; });
def('box_roll', { d: 'the cube tips over its edges and comes to rest', hear: 'a small stone block tumbling to rest on a hard floor', hi: 5000 }, (o, r) => { const st = new St(1.4), cube = dense(r, { lo: 560, hi: 3600, n: 18, t60: .05, roll: .3, tilt: 0 }), tile = dense(r, { lo: 150, hi: 1100, n: 16, t60: .06, roll: .5, tilt: .2 }); let t = 0, g = .07; for (let k = 0; k < 9; k++) { const a = (1 - k / 11) * (k % 2 ? .55 : 1) * r.u(.8, 1.1); strike(st, r, t, cube, { tc: .0013, rough: 1.2, a: .6 * a, pan: -.2 + .06 * k, hits: [[0, 1], [r.u(.006, .014), .4]] }); strike(st, r, t, tile, { tc: .0024, rough: 1.4, a: .7 * a, pan: -.2 + .06 * k }); nb(st, r, t, 400, 2000, .004, .05, .22 * a, { pan: -.2 + .06 * k }); t += g; g *= k > 5 ? .86 : 1.17; } return st; });
def('fluoro_buzz', { d: 'one fluorescent tube failing: soft ballast hum, starter tink, arc crackle in stutters', hear: 'a flickering fluorescent light hum', hi: 3200, cat: 'amb', fade: [.05, .2], def: { dur: 2 } }, (o, r) => { const d = o.dur, st = new St(d), n = N(d), g = new Float64Array(n); let t = 0, on = true; const starts = []; if (o.dips) { g.fill(.95); for (const q of o.dips) { for (let i = N(q); i < Math.min(n, N(q + .045)); i++) g[i] = .05; if (q + .045 < d) starts.push(q + .045); } t = d; } while (t < d) { const L = on ? r.u(.14, .7) : r.u(.04, .2), lv = on ? r.u(.6, 1) : .08; for (let i = N(t); i < Math.min(n, N(t + L)); i++) g[i] = lv; if (on && t > 0) starts.push(t); t += L; on = !on; } lp(g, 22); const hum = new Float64Array(n), w = wander(r, n, 4); let ph = 0; for (let i = 0; i < n; i++) { ph += 100 * (1 + .004 * w[i]) / SR; hum[i] = (Math.sin(TAU * ph) + .22 * Math.sin(TAU * 2 * ph + 1) + .07 * Math.sin(TAU * 3 * ph + 2)) * (.35 + .65 * g[i]); } st.add(hum, { g: .22, pan: .12 }); const air2 = band(r, n, 600, 2400, pink), z = wander(r, n, 33); for (let i = 0; i < n; i++) air2[i] *= g[i] * (.5 + .5 * Math.abs(z[i])); st.add(unit(air2), { g: .1, pan: .2 }); for (const s of starts) { strike(st, r, s, dense(r, { lo: 700, hi: 3000, n: 12, t60: .06, roll: .3 }), { tc: .0014, rough: 1.2, a: .5, pan: .15 }); for (let k = 0; k < r.i(2, 6); k++) grain(st, r, s + r.u(0, .12), r.log(800, 2200), 1.2, 1.6, .3 * r(), .15); } for (const q of poisson(r, d, 14)) { const i = N(q); if (g[Math.min(n - 1, i)] > .3) grain(st, r, q, r.log(700, 2000), 1.4, r.u(1, 3), .2 * r(), .15); } return st; });
def('rope_creak', { d: 'bindings tighten', hear: 'rope creak', hi: 3000 }, (o, r) => { const st = new St(.6), c = slip(r, .42, t => 34 + 40 * t, { jit: .2, tc: .002 }); st.add(bank(c, [[210, .03, 1], [330, .025, .8], [540, .016, .4]], N(.55)), { g: .5 }); return st; });
