def('ember_crackle', { d: 'a burnt place: low breath of heat, resin popping softly, embers drifting by', hear: 'a soft dying fire with gentle crackles', hi: 4000, cat: 'amb', fade: [.3, .4], def: { dur: 3 } }, (o, r) => { const d = o.dur, st = new St(d), n = N(d); for (const c of [0, 1]) { const x = band(r, n, 80, 500, pink), w = wander(r, n, 7), w2 = wander(r, n, 17); for (let i = 0; i < n; i++) x[i] *= .35 + .4 * Math.abs(w[i]) + .25 * w2[i]; mix(c ? st.r : st.l, unit(x), .26); }
  for (const t of poisson(r, d, 19)) { const s = Math.pow(r(), 2.6), p = r.u(-.9, .9), f = r.log(500, 1900); grain(st, r, t, f, .8, r.u(1, 3), .1 + .6 * s, p); if (s > .3) { grain(st, r, t + .002, f * .5, 1.4, 9, .4 * s, p); for (let k = 0; k < r.i(2, 7); k++) grain(st, r, t + Math.pow(r(), 2) * .12, r.log(600, 2200), 1, r.u(.8, 2), .3 * s * r.u(.3, 1), p + r.u(-.1, .1)); } } return st; });
def('ember_step', { d: 'a tired leather sole on charcoal and broken concrete', hear: 'a slow footstep crunching on charcoal', hi: 4800 }, (o, r) => { const st = new St(.6), p = o.pan ?? 0; const x = buf(.2); pulse(x, 0, .008, 1); st.add(bank(x, [[84, .08, 1], [150, .05, .5]]), { g: .9, pan: p }); for (const t of poisson(r, .3, t => 130 * Math.sin(Math.PI * clamp(t / .3)))) { grain(st, r, t, r.log(700, 2600), 1.4, r.u(.8, 3), .5 * Math.pow(r(), 2), p + r.u(-.15, .15)); if (r() < .2) st.ping(t, r.log(400, 1100), .015, .25, p); } return st; });
def('sea', { d: 'a small wave arrives, topples, and drags back through sand; small water laps behind it', hear: 'a gentle sea wave on a beach', sync: 0, hi: 4800, cat: 'amb', fade: [.5, .7], def: { dur: 4 } }, (o, r) => { const d = o.dur, st = new St(d), n = N(d), brk = o.brk ?? d * .3; const wave = (t0, g, pan) => { for (const c of [0, 1]) { const off = (c ? .1 : -.1) * pan, seg = [[70, 320, .3, .75, -.25], [300, 900, .5, .9, 0], [800, 2000, .46, 1.15, .06], [1800, 4200, .24, 1.0, .16]]; for (const [lo, hi, a, k, dl] of seg) { const b = band(r, n, lo, hi, pink), z = wander(r, n, 8), z2 = wander(r, n, 31); for (let i = 0; i < n; i++) { const u = i / SR - t0 - off - dl, e = u < 0 ? .5 * Math.exp(u * 2.6) : Math.exp(-u * k) * (u < .12 ? .5 + .5 * u / .12 : 1); b[i] *= (e + .34 * Math.exp(-Math.pow((u - 1.7) / .5, 2))) * (.55 + .2 * z[i] + .25 * Math.abs(z2[i])); } mix(c ? st.r : st.l, unit(b), g * a); } } for (const t of poisson(r, 2.4, u => 1300 * Math.exp(-1.1 * u))) if (t0 + t < d) grain(st, r, t0 + t, r.log(600, 3000), 1.4, r.u(1, 4), .12 * g * r.u(.2, 1) * Math.exp(-.4 * t), r.u(-1, 1)); }; wave(brk, 1, 1); if (d > 3.2) wave(brk + d * .52, .55, -1); for (const t of poisson(r, d, 3)) squelch(st, r, { at: t, dur: Math.min(.4, Math.max(.06, d - t)), f0: 300, f1: 1300, q: 1.2, rate: 14, a: .09, pan: r.u(-.9, .9), gate: .6 }); return st; });
def('gull_far', { d: 'one gull, far', hear: 'a distant seagull', hi: 4200 }, (o, r) => { const st = new St(1); [0, .34].forEach((at, k) => { const L = .26, g = glottis(r, L, t => 880 * (1 - .28 * t / L) * (k ? .93 : 1), { oq: .6, jit: .015, breath: .06, tilt: 3500 }), y = formants(g, [[1500, 260, 1], [2600, 400, .4]]); mul(y, t => smooth(t / .04) * smooth((L - t) / .14)); st.add(y, { at, pan: .7 }); }); return st; });
def('collar_turn', { d: 'a head turns: a shirt collar, sea air', hear: 'soft shirt fabric', hi: 3200 }, (o, r) => { const st = new St(.45); cloth(st, r, { dur: .34, lo: 250, hi: 1900, a: .4 }); return st; });
def('glasses_sink', { d: 'goggles break a black water surface and sink: plunge, cavity, air leaving, pressure', hear: 'an object plunging into deep water, muffled underwater bubbles', sync: .015, hi: 2400, fade: [.001, .3] }, (o, r) => { const st = new St(3), T = .015; nb(st, r, T, 300, 2600, .002, .16, 1.1, { wide: .4 }); flesh(st, r, T, { a: .6, mass: 1.2, skin: .6 }); nb(st, r, T + .04, 90, 420, .03, .3, 1.3, { src: pink }); squelch(st, r, { at: T + .03, dur: .5, f0: 120, f1: 520, q: 1.6, rate: 16, a: .8, shape: u => Math.pow(1 - u, 1.3), gate: .7 }); thud(st, .06, 92, 55, .6, 1, { glide: .12, atk: .03 });
  const pre = new St(3); for (const t of poisson(r, 2.4, t => 85 * Math.exp(-1.1 * t))) { const m = r.log(5, 16), p = r.u(-.6, .6), f = 3260 / m; grain(pre, r, .25 + t, f, r.u(1.2, 2.6), r.u(8, 18), .5 * r.u(.2, 1), p); } const L = N(2.9); pre.wide(() => { const x = band(r, L, 45, 520, pink), w = wander(r, L, 5), w2 = wander(r, L, 19); for (let i = 0; i < L; i++) x[i] *= (.45 + .3 * w[i] + .25 * w2[i]) * smooth(i / SR / .3); return unit(x); }, { g: .6 }); pre.each(x => lp4(x, 700)); st.addSt(pre, { at: .05, g: 1 }); strike(st, r, .42, [[640, .09, 1], [1010, .07, .6], [1490, .05, .3]], { tc: .002, rough: .6, a: .12, pan: .1 }); return st; });
def('tear', { d: 'one tear gathers and lets go, as close as skin', hear: 'a tiny soft water drop', sync: .01, hi: 3800 }, (o, r) => { const st = new St(.4), p = o.pan ?? 0; grain(st, r, .01, 900, 1.2, 4, .5, p); grain(st, r, .014, 1250, 6, 22, .9, p); ping(st.l, .016, 1180, .05, .22, 2, .001); ping(st.r, .016, 1180, .05, .22, 2, .001); nb(st, r, .03, 300, 1200, .01, .05, .1, { pan: p }); return st; });
// ================================================================ e4
def('lamp_hum', { d: 'a single street lamp at night', hear: 'a quiet street lamp hum', hi: 2400, cat: 'amb', fade: [.3, .3], def: { dur: 3 } }, (o, r) => { const d = o.dur, st = new St(d), n = N(d); for (const [f, a, p] of [[100, 1, 0], [200, .4, .3], [300, .16, -.3], [400, .12, .2], [600, .05, -.1]]) { const x = new Float64Array(n), w = wander(r, n, 1.5); for (let i = 0; i < n; i++) x[i] = Math.sin(TAU * f * i / SR) * (1 + .1 * w[i]); st.add(x, { g: a * .3, pan: p }); } st.wide(() => band(r, n, 80, 500, pink), { g: .5 }); return st; });
def('petals', { d: 'a shadow comes apart into petals: many small soft leaves brushing air', hear: 'a soft flurry of petals', sync: 0, hi: 3000 }, (o, r) => { const d = o.dur ?? 1.3, st = new St(d + .2); for (const t of poisson(r, d, t => 60 * Math.pow(Math.sin(Math.PI * Math.pow(t / d, .6)), 1.4))) { const p = -.4 + 1.1 * t / d + r.u(-.5, .5), L = r.u(.05, .12); nb(st, r, t, r.u(220, 420), r.u(900, 2000), L * .5, L, .34 * r.u(.3, 1), { pan: clamp(p, -1, 1), src: pink }); } whoosh(st, r, { dur: d, f: 460, q: .7, a: .3, pan: x => -.5 + x }); return st; });
def('ink_sink', { d: 'a shadow sinks into ink: one long swallow', hear: 'a slow thick gulp, sinking', sync: .06, hi: 2200 }, (o, r) => { const st = new St(1.5); squelch(st, r, { at: 0, dur: 1, f0: 90, f1: 520, q: 2, rate: 10, a: .9, shape: u => Math.sin(Math.PI * Math.pow(u, .6)), gate: .6 }); squelch(st, r, { at: .05, dur: .9, f0: 160, f1: 900, q: 1.6, rate: 26, a: .4, shape: u => Math.pow(1 - u, 1.4), gate: .85 }); const n = N(.9), x = new Float64Array(n), w = wander(r, n, 9); let ph = 0; for (let i = 0; i < n; i++) { const t = i / SR; ph += TAU * (48 + 60 * Math.exp(-t * 3)) * (1 + .05 * w[i]) / SR; x[i] = (Math.sin(ph) + .3 * Math.sin(2 * ph)) * smooth(t / .14) * smooth((.9 - t) / .4); } st.add(x, { g: .45 }); bubbles(st, r, { at: .2, dur: 1, rate: 16, mm: [7, 24], a: .5, shape: u => Math.exp(-1.6 * u), spread: .3, ring: .15 }); return st; });
def('rain_drop', { d: 'a first drop of rain on asphalt', hear: 'a single raindrop hitting the ground', sync: 0, hi: 4400 }, (o, r) => { const st = new St(.25), p = o.pan ?? 0; grain(st, r, 0, r.u(650, 1150), .8, r.u(4, 7), 1, p); grain(st, r, 0, r.u(1500, 2400), .8, 2, .4, p); nb(st, r, .002, 180, 620, .001, .035, .5, { pan: p, src: pink }); for (let k = 0; k < 4; k++) grain(st, r, r.u(.012, .06), r.u(900, 2200), 1.6, 1.6, .14, p + r.u(-.2, .2)); return st; });
// ================================================================ e5  rain in three distances: v 0 near, 1 mid, 2 far
def('rain', { d: 'rain in three distances: near drops on cloth, stone and puddle; a mid field; a far grey wall', hear: 'rain', hi: 4800, cat: 'amb', fade: [.5, .5], def: { dur: 4, v: 1 } }, (o, r) => {
  const d = o.dur, st = new St(d), n = N(d), v = o.v;
  if (v === 2) { for (const c of [0, 1]) { const x = band(r, n, 240, 2400, pink), w = wander(r, n, .8), w2 = wander(r, n, 6); svf(x, t => 720 + 160 * w[Math.min(n - 1, Math.floor(t * SR))], .5, 'bp'); for (let i = 0; i < n; i++) x[i] *= .88 + .12 * w2[i]; mix(c ? st.r : st.l, unit(x), .7); mix(c ? st.r : st.l, unit(band(r, n, 70, 260, brown)), .25); } }
  if (v === 1) { st.wide(() => { const x = band(r, n, 320, 3200, pink), w = wander(r, n, 90); for (let i = 0; i < n; i++) x[i] *= .85 + .15 * w[i]; return unit(x); }, { g: .5 }); for (const t of poisson(r, d, 420)) { const s = Math.pow(r(), 5); grain(st, r, t, r.log(380, 2300) * (1 - .4 * s), .9, r.u(1.4, 5) * (1 + s), .04 + .26 * s, r.u(-1, 1)); } }
  if (v === 0) { for (const t of poisson(r, d, 34)) { const s = Math.pow(r(), 2), p = r.u(-1, 1), k = r(), a = .1 + .5 * s; if (k < .4) { grain(st, r, t, r.log(420, 1200), .8, r.u(5, 10), a, p); grain(st, r, t, r.log(1200, 2000), .9, 3, a * .3, p); } else if (k < .7) { grain(st, r, t, r.log(500, 1200), 4, r.u(14, 28), a * .7, p); grain(st, r, t, 1500, 1, 3, a * .35, p); for (let j = 0; j < 3; j++) grain(st, r, t + r.u(.01, .06), r.log(700, 1700), 1.5, 3, a * .2, p); } else nb(st, r, t, 160, 1000, .002, .05, a, { pan: p, src: pink }); } st.wide(() => unit(band(r, n, 400, 2000, pink)), { g: .06 }); } return st;
});
def('rain_stop', { d: 'the drops slow, hang, and stop in the air: each tick stretches into a held breath of itself', hear: 'raindrops slowing down and hanging', sync: 0, hi: 4200, fade: [.01, .25], def: { dur: 1 } }, (o, r) => { const d = o.dur, st = new St(d + .4); let t = 0, g = .011, k = 0; while (t < d) { const u = t / d, p = r.u(-1, 1), f = r.log(500, 1900); grain(st, r, t, f, 1 + 2 * u, 2 + 26 * u * u, .7 * (1 - .4 * u), p); if (k % 3 === 0) { const L = N(Math.max(.1, (d - t) * .95)), x = band(r, L, f * .6, f * 1.7, noise); svf(x, f, 18, 'bp'); for (let i = 0; i < L; i++) { const v = i / L; x[i] *= Math.pow(Math.sin(Math.PI * Math.pow(v, .5)), 1.5); } st.add(unit(x), { at: t, g: .1, pan: p }); } t += g * r.u(.6, 1.4); g *= 1.085; k++; } return st; });
def('rain_reverse', { d: 'drops rise: every sound begins with its end and is drawn upward', hear: 'reversed raindrops rising', sync: o => o.dur ?? 1, hi: 4200, fade: [.05, .02], def: { dur: 1 } }, (o, r) => { const d = o.dur, f = new St(d); for (const t of poisson(r, d, t => 24 + 190 * Math.pow(1 - t / d, 1.5))) { const p = r.u(-1, 1), u = 1 - t / d, a = r.u(.2, 1); grain(f, r, t, r.log(420, 1500) * (.8 + .6 * u), 1, r.u(6, 26), .5 * a, p); if (r() < .3) nb(f, r, t, 260, 1400, .001, r.u(.06, .16), .3 * a, { pan: p, src: pink }); } reversed(f); f.wide(() => { const x = band(r, f.n, 350, 3200, pink), w = wander(r, f.n, 13); svf(x, t => 600 + 1500 * Math.pow(t / d, 1.5), .7, 'bp'); for (let i = 0; i < f.n; i++) x[i] *= Math.pow(i / f.n, 2) * (.8 + .2 * w[i]); return unit(x); }, { g: .5 }); return f; });
def('ears_ring', { d: 'ringing ears: two close nerves and cotton', hear: 'a faint tinnitus ringing', hi: 5000, cat: 'amb', fade: [.3, .8], def: { dur: 2.5 } }, (o, r) => { const d = o.dur, st = new St(d), c = CH(o); let f = c[1]; while (f < 1900) f *= 2; cluster(st, r, [[f, .3, -.5, 0, .4], [f * 1.0022, .28, .5, 0, .5], [f * 1.3348, .08, .1, .1, .6], [f * .5, .04, 0, .2, .6]], { dur: d, drift: .0005, am: .12, rel: d * .5 }); const n = N(d); st.wide(() => mul(band(r, n, 60, 260, brown), t => .8), { g: .8 }); return st; });
def('kneel_rubble', { d: 'knees on wet rubble', hear: 'knees hitting wet gravel', hi: 4200 }, (o, r) => { const st = new St(.6); for (const t of [0, .07]) { const x = buf(.2); pulse(x, 0, .011, 1); st.add(bank(x, [[82, .08, 1], [146, .05, .6], [330, .03, .25]]), { at: t, g: 1 }); } crumbs(st, r, { dur: .3, rate: 150, fall: 3, lo: 500, hi: 2200, t60: .012, a: .4 }); bubbles(st, r, { dur: .2, rate: 60, mm: [2, 6], a: .16, shape: u => 1 - u }); return st; });
