  for (const [at, L, f0, f1, lo, p, a] of [[.05, 1.0, 17, 40, 150, -.5, .9], [.55, 1.2, 22, 58, 210, .45, .8], [1.0, 1.0, 13, 30, 115, -.1, 1], [1.5, 1.1, 28, 70, 260, -.7, .7], [1.75, .9, 19, 46, 175, .7, .8]]) { const c = slip(r, L, t => lerp(f0, f1, Math.pow(t / L, 1.4)) * (1 + .25 * Math.sin(t * 7 + at)), { jit: .25, tc: .0045, amp: t => Math.sin(Math.PI * t / L) }), y = bank(c, dense(r, { lo, hi: lo * 9, n: 18, t60: .05, roll: .5, tilt: .15 }), N(L + .2)); st.add(unit(y), { at, g: .6 * a, pan: p }); }
  for (const t of poisson(r, d, t => 7 * Math.sin(Math.PI * t / d))) { const f = r.log(300, 700); strike(st, r, t, dense(r, { lo: f, hi: 3000, n: 14, t60: .07, roll: .4, tilt: .1 }), { tc: .0016, rough: 1, a: r.u(.2, .6), pan: r.u(-.9, .9), hits: [[0, 1], [r.u(.02, .06), .4]] }); }
  for (const c of [0, 1]) { const w = band(r, n, 300, 3000, pink), m = wander(r, n, 9), m2 = wander(r, n, 40); for (let i = 0; i < n; i++) { const t = i / SR; w[i] *= (.45 + .35 * Math.abs(m[i]) + .2 * m2[i]) * Math.pow(sh(t), 1.3); } mix(c ? st.r : st.l, unit(w), .34); } glugs(st, r, { at: .3, dur: d - .4, rate: 2, f: 100, a: .3, spread: .9 }); return st;
