def('hand_take', { d: 'a hand takes a wrist: wool, skin, a grip that means it', hear: 'a hand gently grabbing a sleeve', sync: .03, hi: 3400 }, (o, r) => { const st = new St(.6), p = o.pan ?? 0, f = r.u(.92, 1.08); cloth(st, r, { dur: .12, lo: 180, hi: 1500, a: .6, pan: p, wide: .2 }); const x = buf(.2); pulse(x, 0, .011, 1); st.add(bank(x, [[118 * f, .05, 1], [214 * f, .035, .6], [420 * f, .02, .2]]), { at: .03, g: 1, pan: p }); for (let k = 0; k < 3; k++) nb(st, r, .07 + .03 * k, 240, 1300, .012, .04, .22, { pan: p }); cloth(st, r, { at: .16, dur: .2, lo: 200, hi: 1100, a: .22, pan: p }); return st; });
def('sun_warm', { d: 'the sun comes in: the chord itself opening, no attack anywhere', hear: 'a warm gentle swelling chord of light', sync: 0, hi: 4200, cat: 'amb', fade: [.4, .9], def: { dur: 2.6 } }, (o, r) => { const d = o.dur, st = new St(d), c = CH(o), P = []; c.forEach((f, i) => { for (const [k, a] of [[.5, .3], [1, .34], [2, .2], [3, .07], [4, .06]]) P.push([f * k * (1 + .0012 * r.g()), a, r.u(-.7, .7), .1 * k + .12 * i, d * .45]); }); cluster(st, r, P, { dur: d, drift: .0018, am: .3, rel: d * .4, rate: 1.2 }); st.wide(() => { const n = N(d), x = band(r, n, 500, 2600, pink); return mul(x, t => Math.sin(Math.PI * t / d) ** 2); }, { g: .16 }); return st; });
def('newspaper', { d: 'Nanami turns a page', hear: 'a newspaper page turning', sync: .05, hi: 4600 }, (o, r) => { const st = new St(1), n = N(.44), x = band(r, n, 350, 2600, pink), w = wander(r, n, 18); for (let i = 0; i < n; i++) x[i] *= Math.sin(Math.PI * Math.pow(i / n, .8)) * Math.pow(.55 + .45 * w[i], 1.6); st.add(unit(x), { g: .5, pan: t => .5 - 1.4 * t }); rustle(st, r, { dur: .7, rate: 260, lo: 450, hi: 2600, a: .8, ms: [1, 6], shape: u => Math.pow(Math.sin(Math.PI * u), .8), spread: .35, pw: 3, q: 1 }); nb(st, r, .5, 180, 1300, .004, .1, .6, { pan: -.2, src: pink }); return st; });
def('brush_write', { d: 'one calm stroke of a brush: touch, travel, lift', hear: 'a gentle brush stroke on paper', sync: .02, hi: 3800 }, (o, r) => { const d = o.dur ?? .34, st = new St(d + .2), p = o.pan ?? 0, dir = o.dir ?? 1, n = N(d), y = band(r, n, 420, 2700, pink), w = wander(r, n, 40), w2 = wander(r, n, 9); svf(y, t => 900 + 380 * Math.sin(Math.PI * t / d), .6, 'bp'); for (let i = 0; i < n; i++) { const u = i / n; y[i] *= Math.pow(Math.sin(Math.PI * Math.pow(u, .85)), 1.1) * (.75 + .25 * w[i]) * (.8 + .2 * w2[i]); } st.add(unit(y), { at: .02, g: .7, pan: t => p + dir * (-.2 + .4 * t / d) }); nb(st, r, .012, 120, 520, .016, .06, .22, { pan: p - dir * .2, src: pink }); return st; });
def('ink_run', { d: 'wet ink running down paper: a thread of liquid, beads catching', hear: 'a small trickle of liquid', sync: 0, hi: 3600, def: { dur: 1.1 } }, (o, r) => { const d = o.dur, st = new St(d + .2), n = N(d); bubbles(st, r, { dur: d, rate: 62, mm: [2.2, 6], a: .5, shape: u => Math.sin(Math.PI * Math.pow(u, .6)), spread: .25, xi: .25 }); const x = band(r, n, 500, 2400, pink), w = wander(r, n, 11); for (let i = 0; i < n; i++) x[i] *= (.4 + .6 * w[i] * w[i]) * Math.sin(Math.PI * i / n); st.add(x, { g: .3 }); return st; });
def('seal_stamp', { d: 'a stone seal pressed on paper on a wooden desk, held, lifted from its paste', hear: 'a stamp pressed on paper on a desk', sync: .02, hi: 4400 }, (o, r) => { const st = new St(.8); flesh(st, r, .02, { a: .8, mass: 1, skin: .5 }); strike(st, r, .02, dense(r, { lo: 120, hi: 2200, n: 34, t60: .08, roll: .6, tilt: .25 }), { tc: .003, rough: 1.4, a: .9, hits: [[0, 1], [.011, .25]] }); nb(st, r, .02, 300, 1800, .001, .06, .9); for (let t = .36; t < .47;) { grain(st, r, t, r.log(500, 1500), 1.6, r.u(2, 4), .22 * r.u(.4, 1), .05); t += r.exp(.007); } squelch(st, r, { at: .38, dur: .1, f0: 400, f1: 1300, q: 2, rate: 30, a: .2 }); return st; });
def('petal_land', { d: 'petals settle on paper', hear: 'petals softly landing on paper', hi: 4000 }, (o, r) => { const st = new St(1.6); for (const t of poisson(r, 1.4, 12)) { const p = r.u(-.8, .8); nb(st, r, t, 350, 1500, .012, .03, .3 * r.u(.4, 1), { pan: p }); grain(st, r, t + .02, r.log(700, 1500), 1.4, 2.4, .4 * r.u(.4, 1), p); } return st; });
def('pencil_letters', { d: 'small letters written by hand under the kanji', hear: 'pencil writing on paper', hi: 4800, def: { dur: 1 } }, (o, r) => { const d = o.dur, st = new St(d + .1); let t = 0; while (t < d) { const L = r.u(.03, .085), n = N(L), x = band(r, n, 900, 3800), w = wander(r, n, 300), f = r.u(1500, 2300); svf(x, u => f * (1 + 4 * u), 1.2, 'bp'); for (let i = 0; i < n; i++) x[i] *= Math.sin(Math.PI * i / n) * (.4 + .6 * w[i] * w[i]); st.add(x, { at: t, g: 1.2, pan: -.35 + .7 * t / d }); if (r() < .5) st.ping(t, r.u(420, 600), .02, .1, -.35 + .7 * t / d); t += L + r.u(.015, .06); } return st; });
